const response = $input.first().json;
const hits = response.hits?.hits ?? [];

if (hits.length === 0) {
  return [];
}

return hits.map((hit) => {
  const source = hit._source ?? {};
  const parameters = source['kibana.alert.rule.parameters'] ?? {};

  const ruleMetadata = {};
  const evidence = {};

  for (const [key, value] of Object.entries(source)) {
    if (key.startsWith('kibana.alert.rule.')) {
      ruleMetadata[key] = value;
    } else if (!key.startsWith('kibana.alert.')) {
      evidence[key] = value;
    }
  }

  return {
    json: {
      alert: {
        id: hit._id,
        index: hit._index,
        timestamp: source['@timestamp'] ?? null,
        status: source['kibana.alert.status'] ?? null,
        workflow_status: source['kibana.alert.workflow_status'] ?? null,
        reason: source['kibana.alert.reason'] ?? null,
        url: source['kibana.alert.url'] ?? null
      },
      rule: {
        id: source['kibana.alert.rule.rule_id'] ?? parameters.rule_id ?? null,
        uuid: source['kibana.alert.rule.uuid'] ?? null,
        name: source['kibana.alert.rule.name'] ?? null,
        description: source['kibana.alert.rule.description'] ?? parameters.description ?? null,
        severity: source['kibana.alert.rule.severity'] ?? parameters.severity ?? null,
        risk_score: source['kibana.alert.rule.risk_score'] ?? parameters.risk_score ?? null,
        tags: source['kibana.alert.rule.tags'] ?? [],
        interval: source['kibana.alert.rule.interval'] ?? null,
        from: source['kibana.alert.rule.from'] ?? parameters.from ?? null,
        to: source['kibana.alert.rule.to'] ?? parameters.to ?? null,
        type: parameters.type ?? null,
        language: parameters.language ?? null,
        esql_query: parameters.query ?? null,
        false_positives: parameters.false_positives ?? [],
        threat: parameters.threat ?? [],
        references: parameters.references ?? [],
        parameters,
        metadata: ruleMetadata
      },
      execution: {
        uuid: source['kibana.alert.rule.execution.uuid'] ?? null,
        timestamp: source['kibana.alert.rule.execution.timestamp'] ?? null,
        type: source['kibana.alert.rule.execution.type'] ?? null
      },
      evidence
    },
    pairedItem: { item: 0 }
  };
});

const alertItems = $items('Extract Alert Details', 0, 0);
const timingItems = $input.all();

return timingItems.map((item, index) => {
  const details = alertItems[index]?.json;
  if (!details) {
    throw new Error(`No matching alert details for timing item ${index}`);
  }

  const timing = item.json.hits?.hits?.[0]?._source ?? null;
  const durationNs = timing?.event?.duration == null ? null : Number(timing.event.duration);
  const scheduleDelayNs = timing?.kibana?.task?.schedule_delay == null
    ? null
    : Number(timing.kibana.task.schedule_delay);

  return {
    json: {
      ...details,
      execution: {
        ...details.execution,
        timing_found: timing !== null,
        scheduled_at: timing?.kibana?.task?.scheduled ?? null,
        started_at: timing?.event?.start ?? null,
        ended_at: timing?.event?.end ?? timing?.['@timestamp'] ?? null,
        outcome: timing?.event?.outcome ?? null,
        status: timing?.kibana?.alerting?.status ?? null,
        revision: timing?.kibana?.alert?.rule?.revision ?? null,
        event_duration_ms: Number.isFinite(durationNs) ? durationNs / 1000000 : null,
        schedule_delay_ms: Number.isFinite(scheduleDelayNs) ? scheduleDelayNs / 1000000 : null,
        metrics: timing?.kibana?.alert?.rule?.execution?.metrics ?? {}
      }
    },
    pairedItem: { item: index }
  };
});

const payloadItems = $items('Build Investigation Payload', 0, 0);

const asString = (value, fallback = '') => {
  if (value == null) return fallback;
  if (typeof value === 'string') return value;
  try { return JSON.stringify(value); } catch { return String(value); }
};
const asStringArray = (value) => Array.isArray(value)
  ? value.map((entry) => asString(entry)).filter(Boolean)
  : [];
const enumValue = (value, allowed, fallback) => allowed.includes(value) ? value : fallback;
const objectValue = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};

const parseModelOutput = (item) => {
  let candidate = item.json?.output ?? item.json?.text ?? item.json;
  if (candidate && typeof candidate === 'object' && !Array.isArray(candidate)) return { value: candidate, warning: '' };
  const raw = String(candidate ?? '').trim();
  if (!raw) return { value: {}, warning: 'The model returned an empty response.' };
  const unfenced = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const start = unfenced.indexOf('{');
  const end = unfenced.lastIndexOf('}');
  const jsonText = start >= 0 && end > start ? unfenced.slice(start, end + 1) : unfenced;
  try {
    return { value: JSON.parse(jsonText), warning: '' };
  } catch (error) {
    return { value: {}, warning: `The model response was not valid JSON: ${error.message}` };
  }
};

return $input.all().map((item, index) => {
  const payload = payloadItems[index]?.json;
  if (!payload) throw new Error(`No source investigation payload for AI result ${index}`);

  const parsed = parseModelOutput(item);
  const source = objectValue(parsed.value?.output ?? parsed.value);
  const queryAssessment = objectValue(source.query_assessment);
  const timingAssessment = objectValue(source.timing_assessment);
  const context = objectValue(source.broadened_context_assessment);
  const confidenceNumber = Number(source.confidence);
  const limitations = asStringArray(source.investigation_limitations);
  if (parsed.warning) limitations.unshift(parsed.warning);

  const triage = {
    verdict: enumValue(source.verdict, ['true_positive', 'benign_positive', 'false_positive', 'needs_investigation'], 'needs_investigation'),
    priority: enumValue(source.priority, ['critical', 'high', 'medium', 'low'], 'medium'),
    confidence: Number.isFinite(confidenceNumber) ? Math.min(1, Math.max(0, confidenceNumber)) : 0,
    summary: asString(source.summary, parsed.warning || 'AI triage requires manual review.'),
    reasoning: asStringArray(source.reasoning),
    evidence: Array.isArray(source.evidence) ? source.evidence.map((entry) => {
      const value = objectValue(entry);
      return {
        field: asString(value.field, 'unknown'),
        value: asString(value.value),
        significance: asString(value.significance)
      };
    }) : [],
    query_assessment: {
      logic: asString(queryAssessment.logic),
      matched_condition: asString(queryAssessment.matched_condition),
      limitations: asStringArray(queryAssessment.limitations)
    },
    timing_assessment: {
      run_health: enumValue(timingAssessment.run_health, ['healthy', 'degraded', 'failed', 'unknown'], 'unknown'),
      summary: asString(timingAssessment.summary, 'No timing assessment was returned by the model.')
    },
    recommended_actions: asStringArray(source.recommended_actions),
    workflow_status_recommendation: enumValue(source.workflow_status_recommendation, ['open', 'acknowledged', 'closed'], 'open'),
    investigation_queries: asStringArray(source.investigation_queries),
    investigation_findings: asStringArray(source.investigation_findings),
    investigation_limitations: limitations,
    broadened_context_assessment: {
      population_summary: asString(context.population_summary, 'No broader population query was executed by this workflow.'),
      comparison: asString(context.comparison, 'No executed comparison is available.'),
      anomalies: asStringArray(context.anomalies),
      limitations: asStringArray(context.limitations)
    }
  };

  return {
    json: {
      schema_version: '1.0',
      generated_at: new Date().toISOString(),
      alert: payload.alert,
      rule: payload.rule,
      execution: payload.execution,
      evidence: payload.evidence,
      triage
    },
    pairedItem: { item: index }
  };
});

const investigations = $input.all().map((item) => item.json);

const cell = (value) => String(value ?? '')
  .replace(/\|/g, '\\|')
  .replace(/\r?\n/g, ' ');

const compact = (value, maxLength) => {
  const text = cell(value).replace(/\s+/g, ' ').trim();
  return text.length <= maxLength ? text : `${text.slice(0, maxLength - 1).trimEnd()}…`;
};

const shortTime = (value) => {
  const date = new Date(value);
  if (!Number.isFinite(date.getTime())) return compact(value, 24);
  return date.toISOString().replace('T', ' ').replace(/:\d{2}\.\d{3}Z$/, 'Z');
};

const header = '| Time | Rule | Severity | Risk | Priority | Summary | Suggestion |';
const divider = '|---|---|---|---:|---|---|---|';
const rows = investigations.map((result) => {
  const actions = Array.isArray(result.triage?.recommended_actions)
    ? result.triage.recommended_actions
    : [];
  const suggestion = actions[0]
    ?? `Set status to ${result.triage?.workflow_status_recommendation ?? 'open'}`;

  return `| ${shortTime(result.alert?.timestamp)} | ${compact(result.rule?.name, 48)} | ${compact(result.rule?.severity, 12)} | ${compact(result.rule?.risk_score, 8)} | ${compact(result.triage?.priority, 10)} | ${compact(result.triage?.summary, 160)} | ${compact(suggestion, 120)} |`;
});

return [{
  json: {
    count: investigations.length,
    investigations,
    markdown_table: [header, divider, ...rows].join('\n')
  }
}];

const normalizeQuery = (value) => {
  const query = String(value ?? '').replace(/^```(?:esql)?\s*/i, '').replace(/\s*```$/i, '').trim();
  if (!query) return '';
  return /\|\s*LIMIT\s+2\s*;?\s*$/i.test(query) ? query : `${query.replace(/;\s*$/, '')}\n| LIMIT 2`;
};

return $input.all().map((item, index) => {
  const triage = (item.json.triage && typeof item.json.triage === 'object') ? item.json.triage : {};
  const queries = Array.isArray(triage.investigation_queries)
    ? triage.investigation_queries.map(normalizeQuery).filter(Boolean)
    : [];
  const findings = Array.isArray(triage.investigation_findings) ? triage.investigation_findings : [];
  return {
    json: {
      ...item.json,
      investigation: {
        queries,
        broadened_esql_query: queries.join('\n\n'),
        findings,
        stats: null
      }
    },
    pairedItem: { item: index }
  };
});

const table = $items('Render Markdown Table', 0, 0)[0]?.json.markdown_table ?? '';
const results = $items('Enrich Final Investigation JSON', 0, 0);

const cell = (value) => String(value ?? '')
  .replace(/\|/g, '\\|')
  .replace(/\r?\n/g, '<br>');
const bullets = (values) => (Array.isArray(values) && values.length ? values : ['None supplied.'])
  .map((value) => `- ${cell(value)}`).join('\n');

return results.map((item, index) => {
  const result = item.json;
  const triage = result.triage ?? {};
  const query = result.rule?.esql_query ?? '';
  const broadened = result.investigation?.broadened_esql_query ?? '';
  const context = triage.broadened_context_assessment ?? {};
  const markdown = [
    '# SOC alert investigation',
    '',
    `- Alert ID: ${cell(result.alert?.id)}`,
    `- Rule: ${cell(result.rule?.name)}`,
    `- Alert time: ${cell(result.alert?.timestamp)}`,
    `- Verdict: ${cell(triage.verdict)}`,
    `- Priority: ${cell(triage.priority)}`,
    `- Confidence: ${cell(triage.confidence)}`,
    `- Recommended workflow status: ${cell(triage.workflow_status_recommendation)}`,
    '',
    '## Summary',
    triage.summary ?? '',
    '',
    '## Detection ES|QL',
    '```esql',
    query,
    '```',
    '',
    '## Agent-derived investigation queries',
    '```esql',
    broadened,
    '```',
    '',
    `Population: ${context.population_summary ?? 'Not supplied.'}`,
    `Comparison: ${context.comparison ?? 'Not supplied.'}`,
    '',
    '### Aggregate observations',
    bullets(context.anomalies),
    '',
    '## Reasoning',
    bullets(triage.reasoning),
    '',
    '## Evidence',
    ...(Array.isArray(triage.evidence) && triage.evidence.length
      ? triage.evidence.map((entry) => `- **${cell(entry.field)}** = ${cell(entry.value)}: ${cell(entry.significance)}`)
      : ['- None supplied.']),
    '',
    '## Recommended actions',
    bullets(triage.recommended_actions),
    '',
    '## Limitations',
    bullets([...(triage.query_assessment?.limitations ?? []), ...(context.limitations ?? [])]),
    '',
    '## Batch triage table',
    table
  ].join('\n');

  return {
    json: {
      ...result,
      markdown,
      markdown_table: table
    },
    pairedItem: { item: index }
  };
});

const sourceItems = $items('Prepare Alert Markdown', 0, 0);
return $input.all().map((item, index) => ({
  json: {
    ...sourceItems[index]?.json,
    alert_update: item.json
  },
  pairedItem: { item: index }
}));
